// Une vague simple : on tire sur tout ce qui bouge en visant l'ennemi le plus proche.
function play(wave, seconds, aimAt = true) {
  for (let t = 0; t < seconds && !wave.over; t += 1 / 60) {
    // Un joueur raisonnable : il détruit d'abord les tirs ennemis proches, vise le boss s'il est là, sinon l'ennemi le plus proche.
    if (aimAt && wave.enemies.length) { const bolt = wave.enemies.filter(e => e.def.shot && e.z < 30).sort((a, b) => a.z - b.z)[0], orb = wave.puzzle ? wave.puzzle.orbs.find(o => o.num === wave.puzzle.next) : null, healer = wave.enemies.find(e => !e.dead && e.def.heal && e.z < 60); const e = orb || bolt || (wave.boss && !wave.boss.dead ? wave.boss : healer || wave.enemies.reduce((a, b) => (a.z < b.z ? a : b))); const p = CB.project(e); wave.aim.x = p.x; wave.aim.y = p.y; }
    wave.fire(); wave.update(1 / 60);
    if (wave.choice) wave.pickCard(0);
  }
}
